// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2010, "4-5", [{"author":"И. Рубанов","question":"Сколько букв стоит в русском алфавите между буквами <em>Е</em> и <em>К</em>?","choices":["две","три","четыре","пять","шесть."],"key":"Г","review":["Между буквами Е и К","Прочитай этот кусочек алфавита целиком: Е, Ё, Ж, З, И, Й, К.","Края «Е» и «К» не считаются. Между ними остались «Ё», «Ж», «З», «И» и «Й», всего пять."]},{"author":"И. Иткин","question":"Основная денежная единица Болгарии называется <em>лев</em>. А какую часть лева составляет <em>стотинка</em>?","choices":["половину","четверть","седьмую часть","десятую часть","сотую часть."],"key":"Д","review":["Болгарские деньги","Название «стотинка» напоминает «сто» и «сотый». Как копейка у рубля, это мелкая часть основной денежной единицы.","В одном болгарском леве сто стотинок. Значит, одна стотинка составляет сотую часть лева."]},{"author":"Т. Руссита","question":"Выберите место, где не принято лежать.","choices":["<em>ложе</em>","<em>лежак</em>","<em>лежбище</em>","<em>ложа</em>","<em>лежанка</em>."],"key":"Г","review":["Место для отдыха","Ложе, лежак и лежанка подходят для того, чтобы лечь, а на лежбище отдыхают животные.","Ложа — отдельная группа мест в театре. Зрители там сидят, поэтому она отличается от остальных."]},{"author":"С. Переверзева","question":"Однажды буква Я, героиня сказки Бориса Заходера, гордо заявила:\nЯ ведь вам не просто буква,\nЯ — местоимение.\nА какая ещё буква могла бы вслед за Я справедливо сказать, что она — «не просто буква»?","choices":["<em>Р</em>","<em>Т</em>","<em>У</em>","<em>Ф</em>","<em>Ю</em>."],"key":"В","review":["Буква, которая ещё и слово","Буква «Я» может стать целым словом: «Я читаю». Ищи другую букву, которую можно написать отдельно в обычном предложении.","«У» бывает предлогом, как в «Кот сидит у окна». Это отдельное слово, хотя состоит из одной буквы."]},{"author":"Н. Валеева","question":"Какое из этих действий реже остальных имеет отношение к еде?","choices":["<em>переборщить</em>","<em>переперчить</em>","<em>пересолить</em>","<em>переварить</em>","<em>пережарить</em>."],"key":"А","review":["Действия на кухне","«Переперчить», «пересолить», «переварить» и «пережарить» можно про блюдо, если перца, соли или времени готовки оказалось слишком много.","«Переборщить» значит вообще сделать что-то чрезмерно. Например, можно переборщить с громкостью музыки. Связь с едой для этого слова необязательна."]},{"author":"С. Бурлак","question":"Какое слово не однокоренное с остальными?","choices":["<em>долг</em>","<em>должник</em>","<em>должен</em>","<em>одолжение</em>","<em>продолжение</em>."],"key":"Д","review":["Семья слов со словом «долг»","С долгом связаны «должник», «должен» и «одолжение». В корне «г» чередуется с «ж».","В слове «продолжение» есть другой смысл: то, что продолжается, длится дальше. Оно связано со временем или длиной, а слова про долг относятся к обязанности."]},{"author":"И. Иткин","question":"<em>Доктор Айболит вылечил ... лапу</em>.\nКаким словом лучше всего заполнить пропуск?","choices":["<em>оленёнку</em>","<em>ослёнку</em>","<em>львёнку</em>","<em>жуку</em>","ни один из ответов (А)–(Г) не подходит."],"key":"В","review":["Пациент Айболита","Оленёнок и ослёнок ходят на копытах. У жука говорят о лапках или ножках.","У львёнка лапы, как у взрослого льва или кошки. Поэтому «Айболит вылечил львёнку лапу» подходит лучше всего."]},{"author":"Е. Муравенко","question":"Что обычно не помещают в комнату?","choices":["[ДИВАН]","[СТОЛ]","[КРЕСЛО]","[ПОЛКА]","[АВТОБУС]."],"key":"Д","review":["Ребусы про комнату","В варианте Д буква «а» стоит внутри «т»: получается «а в т». Затем добавь «о» и прочитай «бусы» без последней буквы: «бус».","Вышло «автобус». Диван, стол, кресло и полку обычно ставят в комнате, автобус ездит по дороге."],"figure":{"options":[{"src":"assets/medvezhonok/2010/4-5-8-1.webp","width":121,"height":67,"pixelWidth":121,"pixelHeight":67,"description":"Единица между запятыми, затем Н внутри А"},{"src":"assets/medvezhonok/2010/4-5-8-2.webp","width":126,"height":53,"pixelWidth":126,"pixelHeight":53,"description":"Число 100 и буква л"},{"src":"assets/medvezhonok/2010/4-5-8-3.webp","width":194,"height":63,"pixelWidth":194,"pixelHeight":63,"description":"Буква К, нота ре и слон с запятой после него"},{"src":"assets/medvezhonok/2010/4-5-8-4.webp","width":74,"height":76,"pixelWidth":74,"pixelHeight":76,"description":"Маленькие слоги Ка на большой букве Л"},{"src":"assets/medvezhonok/2010/4-5-8-5.webp","width":198,"height":87,"pixelWidth":198,"pixelHeight":87,"description":"Маленькая а внутри Т, затем о и бусы с запятой после них"}],"onlyPictures":true}},{"author":"О. Шеманаева","question":"В каком из словосочетаний употреблено несуществующее слово?","choices":["<em>переизданный учебник</em>","<em>перезаряженное ружьё</em>","<em>пересгоревшая лампочка</em>","<em>переизбранный президент</em>","<em>перевыполненный план</em>."],"key":"В","review":["Слова с приставкой «пере-»","Учебник можно издать заново, ружьё зарядить снова, президента избрать ещё раз, а план выполнить сверх нормы. Приставка «пере-» передаёт здесь повтор или превышение.","Про перегоревшую лампочку так и говорят «перегорела». Формы «пересгоревшая» в обычном русском нет."]},{"author":"И. Иткин","question":"Кто из русских поэтов в шутку жаловался, что его фамилия обозначается «буквой-раскорякой»?","choices":["Е. А. Баратынский","А. С. Грибоедов","В. А. Жуковский","А. Н. Плещеев","А. С. Пушкин."],"key":"В","review":["Буква в фамилии поэта","Сравни первые буквы фамилий. «Б», «Г» и «П» выглядят проще, а у «Ж» в середине пересекаются сразу несколько штрихов.","Именно «Ж» похоже на раскоряку с растопыренными «ногами». На эту букву начинается фамилия Жуковского."]},{"author":"С. Переверзева","question":"14:00 — 2 часа пополудни. А 3:00?","choices":["3 часа пополуночи","3 часа пополутра","3 часа дополудни","3 часа до полудня","3 часа пополвечера."],"key":"А","review":["После полудня и полуночи","Полдень — 12:00, а полночь — 0:00. «Пополудни» в примере означает «после полудня».","В 3:00 после полуночи прошло три часа. По тому же образцу говорят «три часа пополуночи»."]},{"author":"О. Шеманаева","question":"Вот начала слов: <em>корабле</em>-, <em>море</em>-, <em>земле</em>-, <em>место</em>-. Как нельзя продолжить ни одно из них?","choices":["-<em>трясение</em>","-<em>кружение</em>","-<em>положение</em>","-<em>крушение</em>","-<em>плавание</em>."],"key":"Б","review":["Начала и концы слов","Соедини подходящие части: «корабле-крушение», «море-плавание», «земле-трясение», «место-положение». Получились четыре известных слова.","«-Кружение» осталось без пары. Есть слово «головокружение», а начала «голово-» среди данных нет."]},{"author":"Б. Иомдин","question":"Что, скорее всего, скажет мама двоечнику, который вдруг получил пятёрку?","choices":["<em>это не дело</em>","<em>ясное дело</em>","<em>другое дело</em>","<em>дело житейское</em>","<em>хорошенькое дело.</em>"],"key":"В","review":["Мама увидела пятёрку","Мама ожидала двойку, а увидела хороший результат. Её фраза должна передать одобрение и удивление перемене.","«Другое дело!» говорят, когда стало заметно лучше. Так мама может похвалить полученную пятёрку."]},{"author":"С. Бурлак","question":"Хочешь <u>бо́льшего</u> — поезжай в <u>Бо́лшево</u>!\nСколькими звуками отличаются друг от друга подчёркнутые слова?","choices":["одним","двумя","тремя","четырьмя","эти слова произносятся абсолютно одинаково."],"key":"А","review":["Большего и Болшево","Произнеси оба слова с ударением на первом «о». Конец «-шего» в этом слове звучит так же, как «-шево», поскольку «г» в окончании «-его» произносится как [в].","Перед «ш» в «бо́льшего» слышно мягкое [л’], а в «Бо́лшево» — твёрдое [л]. Это единственное различие в звуках."]},{"author":"О. Шеманаева","question":"<em>Вор бесшумно прокрался в комнату, и тут скрипнула половица</em>. А что такое <em>половица</em>?","choices":["коврик","доска","дверца","птица","сверчок."],"key":"Б","review":["Что скрипнуло в комнате?","Вор идёт по комнате, и что-то скрипит под ногами. В слове «половица» можно узнать слово «пол».","Половица — одна из досок пола. Если такая доска прогибается под ногой, она может издать скрип."]},{"author":"Е. Вельмезова","question":"Обычно в году 365 дней. А как называется год, в котором 366 дней?","choices":["<em>высокостный</em>","<em>высокосный</em>","<em>високостный</em>","<em>високосный</em>","<em>весокосный</em>."],"key":"Г","review":["Год с лишним днём","Название года с 29 февраля можно проверить по календарю или словарю. Оно начинается с «висо-», хотя на слух может напоминать «высокий».","Пиши «високосный»: «и» после «в» и без «т» перед «н». Слово пришло из старого календарного названия и не связано со словом «высокий»."]},{"author":"И. Рубанов","question":"Сколько различных трёхбуквенных русских слов можно прочитать по строкам и столбцам квадрата из букв:\nЛОМ\nОКО\nВОР?\nЧитать можно слева направо, справа налево, сверху вниз и снизу вверх.","choices":["шесть","семь","восемь","девять","двенадцать."],"key":"Г","review":["Квадрат из букв","Прочитай строки в обе стороны. Выйдут «лом», «мол», «око», «вор», «ров». Средняя строка читается одинаково с обоих концов.","Из столбцов получаются «лов», «вол», «око», «мор», «ром». «Око» уже было среди строк, так что к пяти словам добавились четыре новых. Всего девять."]},{"author":"И. Иткин","question":"Какое растение получило своё название из-за колючек?","choices":["<em>ежевика</em>","<em>малина</em>","<em>ель</em>","<em>роза</em>","<em>чертополох</em>."],"key":"А","review":["Колючее растение","У нескольких растений в списке есть колючки. Ищи в самом названии подсказку к тому, на что эти колючки похожи.","В слове «ежевика» слышится «ёж». Колючки растения напомнили иголки ежа и дали ему имя."]},{"author":"С. Бурлак","question":"В какой из пар глаголы соотносятся по смыслу не так, как в других?","choices":["<em>вбежать</em> — <em>выбежать</em>","<em>вползти</em> — <em>выползти</em>","<em>ввинтить</em> — <em>вывинтить</em>","<em>втащить</em> — <em>вытащить</em>","<em>вручить</em> — <em>выручить</em>."],"key":"Д","review":["Глаголы с «в-» и «вы-»","Вбежать и выбежать — движения внутрь и наружу. Такой же противоположный смысл у пар про ползание, винт и перетаскивание.","«Вручить» значит передать кому-то, а «выручить» — помочь выйти из беды. Это два разных действия, которые не противоположны в том же смысле."]},{"author":"А. Иткин","question":"После какой из этих букв реже всего встречается буква <em>ь</em>?","choices":["<em>ж</em>","<em>ц</em>","<em>ч</em>","<em>ш</em>","<em>щ</em>."],"key":"Б","review":["Мягкий знак после согласных","Найди слова с «ь» после четырёх букв: «рожь» после «ж», «ночь» после «ч», «мышь» после «ш», «вещь» после «щ».","После «ц» мягкий знак в обычных русских словах почти не встречается. Сравни «палец» и «огурец» с примерами выше."]},{"author":"С. Бурлак и К. Кноп","question":"Назовём букву в слове «заменимой», если её можно заменить другой буквой так, чтобы снова получилось осмысленное слово. Например, буква <em>т</em> в слове <em>стена</em> — заменимая, потому что её можно заменить буквой <em>ц</em> и получить слово <em>сцена</em>. А сколько заменимых букв в слове <em>баран</em>?","choices":["одна","две","три","четыре","пять."],"key":"Д","review":["Замены в слове «баран»","Замени по очереди одну из первых трёх букв, каждый раз начиная с «баран». Получатся «таран», «буран» и «бадан». Бадан — растение.","Четвёртая буква меняется в слове «барин», последняя — в слове «барак». Нашёлся пример для каждого из пяти мест, значит, заменимы все буквы."]},{"author":"Л. Фёдорова","question":"Что надо съесть, судя по поговорке, чтобы считаться знатоком в каком-то деле?","choices":["<em>много каши</em>","<em>фунт изюму</em>","<em>пуд соли</em>","<em>собаку</em>","<em>Колобка</em>."],"key":"Г","review":["Поговорка о знатоке","Вспомни выражение «Он в этом деле собаку съел». Здесь необычная еда означает большой опыт.","Выбираем собаку: так говорят о знатоке. Пуд соли упоминают в другой поговорке, о долгом знакомстве с человеком."]},{"author":"А. Сомин","question":"Какой гласной буквой <strong>не</strong> могут заканчиваться склоняемые имена существительные в именительном падеже множественного числа?","choices":["<em>а</em>","<em>е</em>","<em>и</em>","<em>у</em>","<em>я</em>."],"key":"Г","review":["Последняя гласная во множестве","Подбери формы множественного числа: «окна» оканчивается на «а», «горожане» на «е», «кони» на «и», «моря» на «я».","Остаётся «у». У склоняемых существительных в именительном падеже множественного числа такого окончания нет. Например, сходное «кенгуру» вообще не склоняется."]},{"author":"В. Черванёва","question":"Какое из слов по смыслу устроено не так, как остальные?","choices":["<em>птицеед</em>","<em>муравьед</em>","<em>короед</em>","<em>людоед</em>","<em>дармоед</em>."],"key":"Д","review":["Слова на «-ед»","В словах «птицеед», «муравьед», «короед» и «людоед» первая часть подсказывает, что можно есть. Это птицы, муравьи, кора или люди.","«Дармоед» питается даром, за счёт других. Его первая часть указывает, как он получает еду, а не что ест."]},{"author":"А. Пиперски и А. Сомин","question":"Болгарский язык родствен русскому. Какое слово в словаре болгарского языка объясняется как <em>женско говедо</em>?","choices":["<em>животно</em>","<em>крава</em>","<em>свиня</em>","<em>коза</em>","<em>овца</em>."],"key":"Б","review":["Определение по-болгарски","«Женско» похоже на «женское», а «говедо» связано с крупным рогатым скотом. Определение просит назвать самку такого животного.","Это корова. Среди болгарских вариантов «крава» похоже на русское «корова» и означает то же самое."]},{"author":"А. Пиперски","question":"Учитель Кулыгин, персонаж пьесы А. П. Чехова «Три сестры», рассказывает такую историю:\n«<em>В какой-то семинарии учитель написал на сочинении “…”, а ученик прочёл</em> <em>“реникса” — думал, по-латыни написано</em>». Какое слово в цитате заменено многоточием?","choices":["<em>двойка</em>","<em>неправда</em>","<em>отлично</em>","<em>ошибка</em>","<em>чепуха</em>."],"key":"Д","review":["Надпись в сочинении","Представь, что написанное по-русски приняли за латиницу. Рукописная «п» похожа на латинскую n, а «х» — на x.","Слово «чепуха» могло превратиться в глазах ученика в «renixa», особенно если почерк неразборчив. Это и уместная помета к бессмысленному сочинению."]},{"author":"Б. Иомдин","question":"Какое из сочетаний слов (А)–(Г) имеет смысл?","choices":["<em>приплыло ходила</em>","<em>приползло бегала</em>","<em>пришло ползала</em>","<em>прибежало плавала</em>","все сочетания слов (А)–(Г) бессмысленны."],"key":"В","review":["Глагол и второе слово","В «ходила», «бегала» и «плавала» легко узнать глаголы. «Ползала» тоже может быть глаголом, но попробуй услышать в начале «пол-».","«Ползала» здесь означает половину зала по числу людей, которых он вмещает. Поэтому фраза «пришло ползала» описывает, сколько зрителей пришло."]},{"author":"И. Рубанов","question":"<em>Сеголетками</em> называется молодняк рыб и зверей,","choices":["родившийся в этом году","родившийся летом","родившийся весной","родившийся в прошлом году","родившийся сегодня."],"key":"А","review":["Кого называют сеголетком?","Разложи слово на «сего» и «лето». «Сего» значит «этого», а «лето» в старом счёте могло означать год.","Сеголеток родился в этом году. Время года может быть разным, поэтому ответы про лето и весну слишком узкие."]},{"author":"И. Иткин","question":"Максим подготовил пять карточек по теме предстоящего урока. При составлении какой карточки он ошибся?","choices":["<em>матрос</em>, <em>мужество</em>, <em>мышь</em>","<em>задача</em>, <em>знаток</em>, <em>сбор</em>","<em>астроном</em>, <em>оборот</em>, <em>огурец</em>","<em>вода</em>, <em>врач</em>, <em>втулка</em>","<em>ёж</em>, <em>юность</em>, <em>яблоко</em>."],"key":"Г","review":["Пять карточек со словами","Сравни начальные звуки. Например, «задача», «знаток» и «сбор» начинаются на [з], а «ёж», «юность», «яблоко» — на [й’].","В «вода» и «врач» слышится [в], но во «втулка» перед глухим [т] произносится [ф]. Эти три слова оказались на одной карточке, хотя первые звуки разные."]},{"author":"С. Бурлак","question":"В необычном стихотворении Александра Левина «Разные летали» есть такие строки:\n…Удалые щебетали\nКуст сирени тормошили.\nА по крыше магазина\nВажно каркали гуляли…\nКакими частями речи являются в этих строчках слова <em>гуляли</em>, <em>каркали</em>, <em>тормошили</em> и <em>щебетали</em>?","choices":["<em>щебетали</em> и <em>гуляли</em> — существительные, <em>тормошили</em> и <em>каркали</em> — глаголы","<em>щебетали</em> и <em>каркали</em> — существительные, <em>тормошили</em> и <em>гуляли —</em> глаголы","<em>тормошили</em> и <em>гуляли —</em> существительные, <em>щебетали</em> и <em>каркали —</em> глаголы","<em>тормошили</em> и <em>каркали —</em> существительные, <em>щебетали</em> и <em>гуляли —</em> глаголы","<em>щебетали</em>, <em>гуляли</em> и <em>тормошили —</em> существительные, <em>каркали —</em> глагол."],"key":"Б","review":["Необычные слова в стихах","Прочитай первые две строки как одно предложение. «Удалые щебетали» — те, кто тормошил куст сирени. Значит, «щебетали» называют существ, а «тормошили» — то, что они делали.","Дальше «каркали» — те, кто важно гулял по крыше. «Щебетали» и «каркали» здесь существительные, «тормошили» и «гуляли» — глаголы."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
